#!/usr/bin/env python3
"""Differential test for `fate compile` against the oracle goldens.

The expected files under `golden/` are generated by the Java reference
(Script-Recompiler 0.7.11 @ 3433e6f), never hand-written, so a byte-identical match
is the acceptance criterion (ruling R1).

Two kinds of entry, set by `parity` in manifest.json:

  `match`     (default) byte-exact agreement with the golden is required.
  `deviation` accepted divergence from the reference, for input that is not valid Fate
              and where the reference's output is a by-product of ANTLR's error
              recovery. The run must still fail with a diagnosed exit 3, must not
              crash, and must not silently start matching again.

The metadata bundle is NOT committed. It is read from `$FATE_META_DIR` when set, and
otherwise from a small list of local locations. If the goldens, the binary or the
bundle are missing, the test skips loudly with exit 77 (CTest NOT_APPLICABLE) rather
than reporting a vacuous pass.

Usage: run_golden.py <path-to-fate> <testdata-dir>
"""

from __future__ import annotations

import json
import os
import pathlib
import subprocess
import sys
import tempfile

SKIP = 77


def find_meta() -> pathlib.Path | None:
    """Return a metadata directory holding params.csv, or None.

    The whole function runs on any interpreter the runner happens to have, so the
    annotation above is only a hint (`from __future__ import annotations`); without
    it, a host whose default `python3` predates 3.10 raised TypeError here instead
    of reaching the skip path.
    """
    candidates = []

    env = os.environ.get("FATE_META_DIR")

    if env:
        candidates.append(pathlib.Path(env))

    # Default local bundle: the reference checkout's own metadata, if present.
    for base in (pathlib.Path.home() / "Documents/GitHub", pathlib.Path.home()):
        candidates.append(base / "Severed-Chains/patches/meta")

    for c in candidates:
        if (c / "params.csv").is_file():
            return c

    return None


def main(argv: list[str]) -> int:
    if len(argv) < 3:
        print(f"usage: {sys.argv[0]} <fate-binary> <testdata-dir>")
        return 2

    binary = pathlib.Path(argv[1])
    testdata = pathlib.Path(argv[2])

    if not binary.is_file():
        print(f"SKIP: no fate binary at {binary}")
        return SKIP

    manifest = testdata / "manifest.json"
    golden = testdata / "golden"
    fixtures = testdata / "fixtures"

    if not manifest.is_file() or not golden.is_dir():
        print("SKIP: golden corpus not available to this checkout")
        return SKIP

    meta = find_meta()

    if meta is None:
        print("SKIP: no metadata bundle (set FATE_META_DIR or provide "
              "Severed-Chains/patches/meta)")
        return SKIP

    entries = json.loads(manifest.read_text())["fixtures"]
    failures: list[str] = []
    deviations = 0

    for entry in entries:
        fid = entry["id"]
        src = fixtures / f"{fid}.fate"
        want = golden / f"{fid}.expected"

        if not src.is_file() or not want.is_file():
            failures.append(f"{fid}: missing fixture or golden")
            continue

        with tempfile.TemporaryDirectory() as tmp:
            out = pathlib.Path(tmp) / "out.txt"
            cmd = [str(binary), "compile", "-m", str(meta), *entry.get("args", []),
                   "-o", str(out), str(src)]
            cmd = [a.replace("$FIXTURES", str(fixtures)) for a in cmd]

            try:
                proc = subprocess.run(cmd, capture_output=True, text=True, timeout=30)
            except subprocess.TimeoutExpired:
                failures.append(f"{fid}: timed out after 30s")
                continue

            if entry.get("parity") == "deviation":
                # Pinned as an accepted deviation: the bytes are not expected to match,
                # but the properties below still have to hold. A crash (negative return
                # code) or a silent success is a regression. So is a byte-exact match,
                # which would mean the pin is no longer needed and should be retired
                # rather than left to rot.
                if proc.returncode < 0:
                    failures.append(f"{fid}: crashed with signal {-proc.returncode}")
                elif proc.returncode != 3:
                    failures.append(f"{fid}: deviation pin expects a diagnosed failure "
                                    f"(exit 3), got exit {proc.returncode}")
                elif out.is_file() and out.read_bytes() == want.read_bytes():
                    failures.append(f"{fid}: now matches the golden, so the deviation "
                                    "pin is obsolete - set parity back to 'match'")
                else:
                    deviations += 1

                continue

            expected_writes = want.stat().st_size > 0

            if expected_writes and not out.is_file():
                failures.append(f"{fid}: wrote no output, golden has "
                                f"{want.stat().st_size} bytes (rc={proc.returncode})")
                continue

            if not expected_writes and out.is_file() and out.stat().st_size > 0:
                failures.append(f"{fid}: expected no output, got {out.stat().st_size} "
                                f"bytes (rc={proc.returncode})")
                continue

            got = out.read_bytes() if out.is_file() else b""

            if got != want.read_bytes():
                want_bytes = want.read_bytes()
                first = next((i for i in range(min(len(got), len(want_bytes)))
                              if got[i] != want_bytes[i]), min(len(got), len(want_bytes)))
                failures.append(f"{fid}: differs at byte {first} "
                                f"(rc={proc.returncode}, {len(got)} vs {len(want_bytes)} bytes)")

    for f in failures:
        print(f"FAIL {f}")

    if failures:
        print(f"\n{len(failures)} of {len(entries)} fixture(s) did not match the oracle")
        return 1

    strict = len(entries) - deviations
    tail = f", {deviations} pinned deviation(s)" if deviations else ""
    print(f"fate compile: {strict}/{len(entries)} match the oracle goldens{tail}")
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv))
